[29433] = {id=29433,name="Test Your Strength",level=1,requiredLevel=1,faction="both",expansion=4,zoneID=5861,description="For some people, it's all fun and games until someone gets hurt. I call those people, weak. To be the strongest, you have to hurt someone or something. You hurt yourself as you push your body to its limits. You hurt those that threaten the well-being of others. If you want to be the strongest, you have to fight. How bad do you want it? I want you to crush those that would offer a challenge to you, then bring me back proof of your triumphs.",rewardCurrencies={{id=515,amount=10}},starts={{npcID=14832,x=0.48,y=0.67,zoneID=5861}},ends={{npcID=14832,x=0.48,y=0.67,zoneID=5861}},coords={x=0.48,y=0.67,source="quest_giver",zoneID=5861},questType="standard"},
[29636] = {id=29636,name="A Test of Endurance",level=10,requiredLevel=10,faction="both",expansion=4,zoneID=5785,description="I have taught you everything that I can, . It is time you spoke with Instructor Myang . The fights that she stages are less traditional than the sparring matches I am used to. Nevertheless, the path of a traveling adventurer like yourself is unpredictable, and a broad knowledge of fighting styles is an admirable trait. Farewell, , and best of luck on the remainder of your training.",rewardGold=13740,rewardXP=175,starts={{npcID=54922,x=0.432,y=0.246,zoneID=5785}},ends={{npcID=54918,x=0.39,y=0.24,zoneID=5785}},coords={x=0.432,y=0.246,source="quest_giver",zoneID=5785},questType="standard"},
[30031] = {id=30031,name="Taste Test",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="As long as you're here, you might as well help me out. I'm feeling pretty darn unqualified for the task, seeing as I've never drank a drop of beer in my life. You should try a little sample of each of their grains. Let's see if any of this stuff is sweet enough for Uncle Chen.",rewardGold=137400,rewardXP=2090,starts={{npcID=56138,x=0.688,y=0.432,mapID=376}},ends={{npcID=56138,x=0.688,y=0.432,mapID=376}},coords={x=0.688,y=0.432,source="quest_giver",mapID=376},questType="standard"},
[30047] = {id=30047,name="The Chen Taste Test",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,mapID=376,description="Uncle Chen is going to love this. Or... he might tell us to find something sweeter. He's kind of dumb like that. Let's get this grain back to him at Halfhill.",rewardGold=43200,rewardXP=2090,starts={{npcID=56138,x=0.688,y=0.432,mapID=376}},ends={{npcID=56133,x=0.86,y=0.22,mapID=376}},coords={x=0.688,y=0.432,source="quest_giver",mapID=376},questType="standard"},
[31537] = {id=31537,name="Ella's Taste Test",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Well, I finally got the brew made, but I won't know if it's any good unless some people taste it. Would you take my brew and see what the folks in Halfhill think? I... I couldn't face them myself.",rewardGold=137400,rewardXP=2090,starts={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},ends={{npcID=58647,x=0.53,y=0.516,zoneID=5805}},coords={x=0.53,y=0.516,source="quest_giver",zoneID=5805},questType="standard"},
[31669] = {id=31669,name="The Cabbage Test",level=15,requiredLevel=15,faction="both",expansion=4,zoneID=5805,description="Grandpa always said that the bellweather of a true farmer lies in the quality of his cabbage. Any time a new farmer came into town, he'd buy a few heads of cabbage to see what they knew. Now, I'm the new farmer, and this is my big chance to prove myself. Could you plant some cabbage for me?",rewardGold=68700,rewardXP=1045,rewardCurrencies={{id=738,amount=1}},starts={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},ends={{npcID=58646,x=0.522,y=0.488,zoneID=5805}},coords={x=0.522,y=0.488,source="quest_giver",zoneID=5805},questType="standard"},
